    """Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    sql: Union[str, bytes]
    many_params: Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]

    Returns: Tuple[Union[str, bytes], List[Dict[Any, Any]], Any]
    """
    if self.SQLParams.in_style == 'named':
        if not isinstance(many_params[0], dict):
            raise ValueError('Expected `many_params` to be a list of dicts')
    else:
        if not isinstance(many_params[0], tuple):
            raise ValueError('Expected `many_params` to be a list of tuples')

    params_count = len(many_params)
    param_names = self.SQLParams.names
    formatted_params = {param_name: None for param_name in param_names}
    out_params = []

    for i, params in enumerate(many_params):
        formatted_row = self.format(sql, params)
        out_row = []

        if self.SQLParams.in_style == 'named':
            row_params = {k: v for k, v in params.items() if k in param_names}
        else:
            row_params = dict(zip(param_names, params))

        for param_name, param_value in row_params.items():
            if param_value is not None:
                out_row.append(param_value)
                formatted_params[param_name] = param_value
            else:
                out_row.append('')

        out_params.append(out_row)

    return formatted_params, out_params, params_count

