                self.digests_from_previous_versions[digest] = version_dir

        content_dir = os.path.join(self.root_dir, version_dir, "content")
        for file in os.listdir(content_dir):
            file_path = os.path.join(content_dir, file)
            if os.path.isfile(file_path):
                digest = hashlib.sha256(open(file_path, "rb").read()).hexdigest()
                if digest in self.digests_from_previous_versions:
                    raise ValueError(f"Content file '{file_path}' has the same content digest as version {self.digests_from_previous_versions[digest]}.")

    return self

