def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    match = re.match(r"^(\d+)(quarterday|businessday|day|week|month|year)$", frequency)
    if match is None:
        raise ValueError(f"Invalid frequency: {frequency}")
    amount = int(match.group(1))
    unit = match.group(2)
    if unit == "quarterday":
        return datetime.timedelta(days=amount * 91)
    elif unit == "businessday":
        return datetime.timedelta(days=amount * 7)
    elif unit == "day":
        return datetime.timedelta(days=amount)
    elif unit == "week":
        return datetime.timedelta(weeks=amount)
    elif unit == "month":
        return datetime.timedelta(days=amount * 30)
    elif unit == "year":
        return datetime.timedelta(days=amount * 365)
    else:
        raise ValueError(f"Invalid frequency unit: {unit}")

